      es: ["Fundada en 1919 por Adolfo Schwelm.", "Cerca de 75.000 habitantes.", "Fuerte impronta alemana y suiza.", "Escuelas, clubes y restaurantes alemanes.", "Centro de la industria de la yerba mate.", "Situada en la Selva Paranaense.", "Olas migratorias ucranianas y polacas.", "Importante industria forestal."],
      pt: ["Fundada em 1919 por Adolfo Schwelm.", "Cerca de 75.000 habitantes.", "Forte marca alemã e suíça.", "Escolas, clubes e restaurantes alemães.", "Centro da indústria da erva-mate.", "Situada na Selva Paranaense.", "Ondas migratórias ucranianas e polacas.", "Importante indústria florestal."],
      fr: ["Fondée en 1919 par Adolfo Schwelm.", "Environ 75 000 habitants.", "Forte influence allemande et suisse.", "Écoles, clubs et restaurants allemands.", "Centre de l'industrie de la yerba maté.", "Située dans la forêt atlantique.", "Vagues d'immigration ukrainienne et polonaise.", "Industrie forestière importante."],
